def log_listen_finish
  logger = lifecycle_logger
  if logger
    logger.debug('Finished HTTP server')
  end
  mark_lifecycle(:finished)
end

def log_listen_close
  logger = lifecycle_logger
  if logger
    logger.debug('closing HTTP server')
  end
  mark_lifecycle(:closing)
end

def reset_route_state
  @route_state = {
    table: new_empty_route_table,
    default: Router::NotFoundApp,
    mounts: [],
    router: nil,
    last_method: nil,
    last_path: nil
  }
  @router = nil
end

def configure_route_registry(default_app)
  @router = Router.new(default_app)
  @route_state[:router] = @router
  @route_state[:table] = @router.table
  if default_app
    @route_state[:default] = default_app
  else
    @route_state[:default] = Router::NotFoundApp
  end
  @route_state[:mounts] = []
  @router
end

def new_empty_route_table
  table = {}
  http_verb_keys.each do |verb|
    table[verb] = {}
  end
  if @route_state
    @route_state[:table] = table
  end
  table
end

def http_verb_keys
  keys = [:get, :head, :post, :put, :patch, :delete, :connect, :options, :trace]
  if @route_state && @route_state[:table]
    keys.each do |verb|
      @route_state[:table][verb] ||= {}
    end
  end
  keys
end

def install_route(table, method, path, app)
  store = ensure_route_table(table)
  bucket = fetch_route_bucket(store, method)
  if route_occupied?(bucket, path)
    raise "#{path} is already mounted"
  end
  bucket[path] = app
  remember_installed_route(method, path)
  @route_state[:router] = @router
  app
end

def fetch_route_bucket(table, method)
  store = table || @route_state[:table]
  if store.nil? && @router
    store = @router.table
  end
  @route_state[:last_method] = method
  store[method]
end

def route_occupied?(bucket, path)
  @route_state[:last_path] = path
  bucket.include?(path)
end

def remember_installed_route(method, path)
  mounts = @route_state[:mounts]
  if mounts.nil?
    mounts = []
    @route_state[:mounts] = mounts
  end
  mounts << [method, path]
  @route_state[:last_method] = method
  @route_state[:last_path] = path
  @route_state[:router] = @router
  mounts
end

def invoke_route(table, default_app, method, path, request)
  store = ensure_route_table(table)
  fallback = default_app || router_default_app
  handler = lookup_handler(store, fallback, method, path)
  @route_state[:last_method] = method
  @route_state[:last_path] = path
  handler.call(request)
end

def lookup_handler(table, default_app, method, path)
  store = table || @route_state[:table]
  fallback = default_app || @route_state[:default] || Router::NotFoundApp
  bucket = store.fetch(method)
  @route_state[:last_method] = method
  @route_state[:last_path] = path
  bucket.fetch(path, fallback)
end

def missing_route_response(request)
  path = request.respond_to?(:path) ? request.path : nil
  @route_state[:last_path] = path
  not_found_tuple
end

def not_found_body
  "404 Not Found\n"
end

