def handle_http_call(request, router = nil, logger = nil, wrapped = nil)
  if logger
    @dispatch_state[:logger] = logger
  end
  @dispatch_state[:wrapped_request] = wrapped
  method = extract_http_method(request)
  @dispatch_state[:last_method] = method
  resp = dispatch_named(method, request, router)
  wrap_protocol_response(resp)
rescue => e
  record_dispatch_error(e)
