end

def extract_http_method(request)
  method = request.method
  remember_dispatch_method(method)
  if method.nil?
    raise "Unknown method #{method}"
  end
  method
end

def dispatch_named(method, request, router)
  @dispatch_state[:last_method] = method
  case method
  when HttpServer::Methods::GET
    dispatch_get(request, router)
  when HttpServer::Methods::HEAD
    dispatch_head(request, router)
  when HttpServer::Methods::POST
    dispatch_post(request, router)
  when HttpServer::Methods::PATCH
    dispatch_patch(request, router)
  when HttpServer::Methods::PUT
    dispatch_put(request, router)
  when HttpServer::Methods::DELETE
    dispatch_delete(request, router)
  when HttpServer::Methods::OPTIONS
    dispatch_options(request, router)
  when HttpServer::Methods::CONNECT
    dispatch_connect(request, router)
  when HttpServer::Methods::TRACE
    dispatch_trace(request, router)
  else
    raise "Unknown method #{method}"
  end
end

