def route_wrapped_request(name, request, router)
  req = build_request_wrapper(request)
  path = canonical_request_path(req.path)
  @dispatch_state[:canonical_path] = path
  target = router || (@dispatch_state[:app] && @router) || @router
  if target.nil?
    raise "Unknown method #{name}"
  end
  target.route!(name, path, req)
end

def build_request_wrapper(request)
  wrapped = @dispatch_state[:wrapped_request]
  if wrapped.nil?
    path, query = split_request_target(request.path)
    wrapped = PreparedRequest.new(path, query, request)
    @dispatch_state[:wrapped_request] = wrapped
  end
  remember_dispatch_path(request_path_of(wrapped))
  remember_dispatch_query(request_query_of(wrapped))
  wrapped
end

def canonical_request_path(path)
  remember_dispatch_path(path)
  text = with_trailing_slash(path)
  @dispatch_state[:canonical_path] = text
  text
end

def wrap_protocol_response(resp)
  Protocol::HTTP::Response[*resp]
end

def record_dispatch_error(error)
  logger = @dispatch_state[:logger]
  if logger
    logger.error(error)
  end
  error
end

def internal_error_response
  tuple = internal_error_tuple
  Protocol::HTTP::Response[*tuple]
end

